/**
 * Class to build a container representation from the contents of a jar file.
 */
public class JarFiles {
    /**
     * Generates a {@link JibContainerBuilder} from contents of a jar file.
     *
     * @param processor
     * 		jar processor
     * @param jarOptions
     * 		jar cli options
     * @param commonCliOptions
     * 		common cli options
     * @param commonContainerConfigCliOptions
     * 		common command line options shared between jar and war
     * 		command
     * @param logger
     * 		console logger
     * @return JibContainerBuilder
     * @throws IOException
     * 		if I/O error occurs when opening the jar file or if temporary directory
     * 		provided doesn't exist
     * @throws InvalidImageReferenceException
     * 		if the base image reference is invalid
     */
    public static com.google.cloud.tools.jib.api.JibContainerBuilder toJibContainerBuilder(com.google.cloud.tools.jib.cli.ArtifactProcessor processor, com.google.cloud.tools.jib.cli.Jar jarOptions, com.google.cloud.tools.jib.cli.CommonCliOptions commonCliOptions, com.google.cloud.tools.jib.cli.CommonContainerConfigCliOptions commonContainerConfigCliOptions, com.google.cloud.tools.jib.plugins.common.logging.ConsoleLogger logger) throws java.io.IOException, com.google.cloud.tools.jib.api.InvalidImageReferenceException {
        // Use AdoptOpenJDK image as the default base image.
        com.google.cloud.tools.jib.api.JibContainerBuilder containerBuilder;
        if (commonContainerConfigCliOptions.getFrom().isPresent()) {
            containerBuilder = com.google.cloud.tools.jib.cli.ContainerBuilders.create(commonContainerConfigCliOptions.getFrom().get(), java.util.Collections.emptySet(), commonCliOptions, logger);
        } else {
            containerBuilder = (processor.getJavaVersion() <= 8) ? com.google.cloud.tools.jib.api.Jib.from("adoptopenjdk:8-jre") : com.google.cloud.tools.jib.api.Jib.from("adoptopenjdk:11-jre");
        }
        java.util.List<com.google.cloud.tools.jib.api.buildplan.FileEntriesLayer> layers = processor.createLayers();
        java.util.List<java.lang.String> customEntrypoint = commonContainerConfigCliOptions.getEntrypoint();
        java.util.List<java.lang.String> entrypoint = (customEntrypoint.isEmpty()) ? processor.computeEntrypoint(jarOptions.getJvmFlags()) : customEntrypoint;
        containerBuilder.setEntrypoint(entrypoint).setFileEntriesLayers(layers).setExposedPorts(commonContainerConfigCliOptions.getExposedPorts()).setVolumes(commonContainerConfigCliOptions.getVolumes()).setEnvironment(commonContainerConfigCliOptions.getEnvironment()).setLabels(commonContainerConfigCliOptions.getLabels()).setProgramArguments(commonContainerConfigCliOptions.getProgramArguments());
        commonContainerConfigCliOptions.getUser().ifPresent(containerBuilder::setUser);
        commonContainerConfigCliOptions.getFormat().ifPresent(containerBuilder::setFormat);
        commonContainerConfigCliOptions.getCreationTime().ifPresent(containerBuilder::setCreationTime);
        return containerBuilder;
    }
}

