        com.google.cloud.tools.jib.api.buildplan.FileEntriesLayer layer = com.google.cloud.tools.jib.api.buildplan.FileEntriesLayer.builder().setName("classes").addEntry(java.nio.file.Paths.get("path/to/tempDirectory/class1.class"), com.google.cloud.tools.jib.api.buildplan.AbsoluteUnixPath.get("/app/explodedJar/class1.class")).build();
        // === MOCK-STUB-START ===
