        com.google.cloud.tools.jib.api.buildplan.ContainerBuildPlan buildPlan = containerBuilder.toContainerBuildPlan();
        assertEquals("adoptopenjdk:8-jre", buildPlan.getBaseImage());
        assertEquals(com.google.common.collect.ImmutableSet.of(new com.google.cloud.tools.jib.api.buildplan.Platform("amd64", "linux")), buildPlan.getPlatforms());
