        assertEquals(com.google.cloud.tools.jib.api.buildplan.AbsoluteUnixPath.get("/app/explodedJar/class1.class"), ((com.google.cloud.tools.jib.api.buildplan.FileEntriesLayer) (buildPlan.getLayers().get(0))).getEntries().get(0).getExtractionPath());
