class StandardExplodedProcessor implements com.google.cloud.tools.jib.cli.ArtifactProcessor {
    private final java.nio.file.Path jarPath;

    private final java.nio.file.Path targetExplodedJarRoot;

    private final java.lang.Integer jarJavaVersion;

    /**
     * Constructor for {@link StandardExplodedProcessor}.
     *
     * @param jarPath
     * 		path to jar file
     * @param targetExplodedJarRoot
     * 		path to exploded-jar root
     * @param jarJavaVersion
     * 		jar java version
     */
    StandardExplodedProcessor(java.nio.file.Path jarPath, java.nio.file.Path targetExplodedJarRoot, java.lang.Integer jarJavaVersion) {
        this.jarPath = jarPath;
        this.targetExplodedJarRoot = targetExplodedJarRoot;
        this.jarJavaVersion = jarJavaVersion;
    }

    @java.lang.Override
    public java.util.List<com.google.cloud.tools.jib.api.buildplan.FileEntriesLayer> createLayers() throws java.io.IOException {
        throw new java.lang.UnsupportedOperationException();
    }

    @java.lang.Override
    public com.google.common.collect.ImmutableList<java.lang.String> computeEntrypoint(java.util.List<java.lang.String> jvmFlags) throws java.io.IOException {
        throw new java.lang.UnsupportedOperationException();
    }

    @java.lang.Override
    public java.lang.Integer getJavaVersion() {
        throw new java.lang.UnsupportedOperationException();
    }
}

